insert into public.topics (id, format, published, content) values
('tcf-1-presentation', 'tcf-1', true, '{"name":"Expression orale","icon":"mic","color":"sage","axes":[],"role":"un examinateur","id":"tcf-1-presentation","format":"tcf-1","title":"Faisons connaissance","desc":"Parlez de votre quotidien, de votre parcours et de vos projets.","context":"Présentez-vous. Parlez de vos activités, de votre parcours et de vos projets. Répondez aux questions de l’examinateur.","qa":[["Pouvez-vous vous présenter ?","Je m’appelle… Je vis à… et je travaille comme… Pendant mon temps libre, j’aime…","Depuis combien de temps habitez-vous dans cette ville ?"],["Que faites-vous dans la vie ?","Je suis… Mon travail consiste à… J’apprécie surtout…","Pourquoi avez-vous choisi ce domaine ?"],["Quels sont vos loisirs ?","J’aime… parce que… Le week-end dernier, j’ai…","Pratiquez-vous cette activité seul ou avec des amis ?"],["Quels sont vos projets ?","J’aimerais… Pour cela, je…","Qu’est-ce qui vous motive dans ce projet ?"]]}'::jsonb),
('tcf-2-travail', 'tcf-2', true, '{"id":"tcf-2-travail","name":"Travail","icon":"briefcase","color":"peach","title":"Un nouveau départ à l’étranger","desc":"Une opportunité professionnelle vous attend. À vous de poser les bonnes questions.","role":"votre supérieur","context":"Votre entreprise vous propose un poste à l’étranger. Avant de prendre votre décision, renseignez-vous sur les missions, le salaire, les avantages et les conditions de vie.","axes":["missions","rémunération","logement","horaires"],"qa":[["Quelles seront mes principales missions ?","Vous coordonnerez une petite équipe et suivrez les projets de nos clients.","Pourriez-vous me décrire une journée type ?"],["Quel salaire est proposé pour ce poste ?","Le salaire est de 3 200 euros brut par mois, avec une prime annuelle.","Les frais de déplacement sont-ils pris en charge ?"],["L’entreprise m’aide-t-elle à trouver un logement ?","Nous réservons un logement pour votre premier mois.","Et après le premier mois, quelle aide est prévue ?"],["Quelle est la durée de cette mission ?","Le contrat prévoit un an, renouvelable une fois.","Est-il possible de rentrer plus tôt si nécessaire ?"],["Quelles sont les prochaines étapes ?","Nous attendons votre réponse vendredi, puis nous organisons votre départ.","Pourrais-je échanger avec un collègue déjà sur place ?"]],"format":"tcf-2"}'::jsonb),
('tcf-2-vie', 'tcf-2', true, '{"id":"tcf-2-vie","name":"Vie quotidienne","icon":"sofa","color":"sage","title":"Les bonnes affaires du voisin","desc":"Votre voisin déménage : trouvez le meuble qui vous correspond.","role":"votre voisin","context":"Votre voisin part vivre à l’étranger et vend ses meubles. Renseignez-vous sur leur état, leurs dimensions, leur prix et le transport.","axes":["prix","état","dimensions","transport"],"qa":[["Quels meubles vendez-vous ?","Une table, quatre chaises et un canapé.","Est-ce que vous vendez aussi votre télévision ?"],["Dans quel état est le canapé ?","Il a deux ans et il est en très bon état.","Est-ce que je pourrais venir le voir ?"],["Quelles sont les dimensions de la table ?","Elle mesure 160 centimètres de long sur 90 de large.","Est-ce qu’elle est démontable ?"],["Combien demandez-vous pour le canapé ?","Je le vends 180 euros.","Accepteriez-vous 150 euros si je le prends aujourd’hui ?"],["Pourriez-vous m’aider à le transporter ?","Je peux vous aider à le descendre, mais je n’ai pas de véhicule.","Quand seriez-vous disponible pour le retrait ?"]],"format":"tcf-2"}'::jsonb),
('tcf-2-loisirs', 'tcf-2', true, '{"id":"tcf-2-loisirs","name":"Loisirs & sorties","icon":"ticket","color":"lilac","title":"On se fait une toile ?","desc":"Choisissez le film et la séance pour une soirée réussie.","role":"un ami qui travaille au cinéma","context":"Vous êtes en vacances au Canada. Un ami travaille dans un cinéma. Demandez-lui des renseignements sur les films, les horaires et les tarifs pour choisir une séance.","axes":["films","horaires","tarifs","réservation"],"qa":[["Quels films sont à l’affiche cette semaine ?","Une comédie québécoise et un film d’aventure.","Lequel me conseillerais-tu ?"],["À quelle heure commence la prochaine séance ?","La comédie commence à 18 h et à 20 h 30.","Combien de temps dure le film ?"],["Combien coûte une place ?","Le tarif normal est de 14 dollars.","Y a-t-il un tarif étudiant ?"],["Faut-il réserver à l’avance ?","C’est préférable pour la séance du soir.","Peut-on réserver directement en ligne ?"],["Les films sont-ils en français ?","Oui, la comédie est en français et le film d’aventure est sous-titré.","Est-ce que les sous-titres sont en français aussi ?"]],"format":"tcf-2"}'::jsonb),
('tcf-2-transport', 'tcf-2', true, '{"id":"tcf-2-transport","name":"Transports","icon":"train","color":"sand","title":"La ville à portée de main","desc":"Bus, métro, abonnements : apprenez à vous déplacer.","role":"un agent des transports","context":"Vous découvrez une nouvelle ville. Demandez à un agent des renseignements sur les transports en commun, les horaires et les tarifs.","axes":["lignes","horaires","abonnements","trajet"],"qa":[["Quels transports desservent le centre-ville ?","Le métro et les lignes de bus 4 et 12.","Quel est le moyen le plus rapide ?"],["À quelle heure passe le dernier métro ?","À minuit en semaine et à une heure le samedi.","Y a-t-il des bus de nuit ?"],["Combien coûte un abonnement mensuel ?","Il coûte 45 euros et comprend les bus et le métro.","Existe-t-il une réduction pour les étudiants ?"],["Où puis-je acheter les tickets ?","Aux bornes dans les stations ou sur notre application.","Peut-on payer par carte bancaire ?"],["Comment rejoindre la gare depuis ici ?","Prenez la ligne 2 et descendez au quatrième arrêt.","Dois-je changer de ligne ?"]],"format":"tcf-2"}'::jsonb),
('tcf-2-association', 'tcf-2', true, '{"id":"tcf-2-association","name":"Vie associative","icon":"heart","color":"sage","title":"Donner du temps, créer du lien","desc":"Trouvez une association et une mission qui vous ressemblent.","role":"un agent du bureau des associations","context":"Vous souhaitez devenir bénévole dans votre quartier. Interrogez un agent d’accueil sur les associations, les activités, les publics et les disponibilités nécessaires.","axes":["activités","publics","planning","inscription"],"qa":[["Quelles associations recherchent des bénévoles ?","Une banque alimentaire et une association de soutien scolaire.","Laquelle a le plus besoin d’aide actuellement ?"],["Quelles activités pourrais-je faire ?","Distribuer des repas ou accompagner des enfants dans leurs devoirs.","Une expérience particulière est-elle nécessaire ?"],["À quel public s’adressent ces actions ?","Aux familles du quartier et aux enfants de 6 à 12 ans.","Combien de personnes sont accueillies ?"],["Quels sont les horaires proposés ?","Le mercredi après-midi et le samedi matin.","Puis-je venir seulement deux fois par mois ?"],["Comment puis-je m’inscrire ?","Remplissez ce formulaire puis rencontrez le responsable.","Y a-t-il une formation avant de commencer ?"]],"format":"tcf-2"}'::jsonb),
('tcf-2-assurance', 'tcf-2', true, '{"id":"tcf-2-assurance","name":"Services","icon":"shield","color":"peach","title":"Bien assuré, l’esprit tranquille","desc":"Comparez les garanties avant de prendre la route.","role":"un conseiller en assurance automobile","context":"Vous envisagez de souscrire une assurance automobile. Interrogez un conseiller sur les formules, les garanties, les tarifs et les démarches.","axes":["formules","garanties","franchise","contrat"],"qa":[["Quelles formules proposez-vous ?","Une assurance au tiers et une formule tous risques.","Quelle est la différence entre les deux ?"],["Quel est le montant de la cotisation ?","La formule au tiers commence à 35 euros par mois.","Le tarif dépend-il de mon expérience de conduite ?"],["La garantie couvre-t-elle le vol ?","Oui, dans la formule tous risques.","Une franchise reste-t-elle à ma charge ?"],["Quels documents faut-il fournir ?","Votre permis, la carte grise et votre relevé d’informations.","Combien de temps faut-il pour être couvert ?"],["Puis-je résilier mon contrat facilement ?","Les modalités dépendent de votre situation et du contrat.","Pourriez-vous m’expliquer les conditions par écrit ?"]],"format":"tcf-2"}'::jsonb),
('tcf-3-travail', 'tcf-3', true, '{"name":"Expression orale","icon":"mic","color":"sage","axes":["productivité","vie personnelle","relations professionnelles"],"role":"un examinateur","id":"tcf-3-travail","format":"tcf-3","title":"Le télétravail pour tous ?","context":"Pensez-vous que le télétravail devrait être proposé à tous les salariés ? Présentez votre point de vue et justifiez-le avec des exemples.","desc":"Exprimez et défendez votre point de vue.","qa":[["Quelle est votre position ?","À mon avis… Je pense que…","Annoncez clairement votre point de vue."],["Quel exemple concret pouvez-vous donner ?","Par exemple, dans ma ville…","Expliquez le lien entre cet exemple et votre argument."],["Y a-t-il des limites à votre position ?","Il est vrai que… Cependant…","Nuancez votre avis puis concluez."]]}'::jsonb),
('tcf-3-transport', 'tcf-3', true, '{"name":"Expression orale","icon":"mic","color":"sage","axes":["pollution","accessibilité","commerces"],"role":"un examinateur","id":"tcf-3-transport","format":"tcf-3","title":"Une ville sans voitures ?","context":"Faut-il interdire les voitures dans les centres-villes ? Expliquez votre position, les avantages et les limites de cette mesure.","desc":"Exprimez et défendez votre point de vue.","qa":[["Quelle est votre position ?","À mon avis… Je pense que…","Annoncez clairement votre point de vue."],["Quel exemple concret pouvez-vous donner ?","Par exemple, dans ma ville…","Expliquez le lien entre cet exemple et votre argument."],["Y a-t-il des limites à votre position ?","Il est vrai que… Cependant…","Nuancez votre avis puis concluez."]]}'::jsonb),
('tcf-3-association', 'tcf-3', true, '{"name":"Expression orale","icon":"mic","color":"sage","axes":["solidarité","emploi du temps","expérience"],"role":"un examinateur","id":"tcf-3-association","format":"tcf-3","title":"Le bénévolat à l’école ?","context":"Pensez-vous que les jeunes devraient faire du bénévolat pendant leurs études ? Justifiez votre réponse.","desc":"Exprimez et défendez votre point de vue.","qa":[["Quelle est votre position ?","À mon avis… Je pense que…","Annoncez clairement votre point de vue."],["Quel exemple concret pouvez-vous donner ?","Par exemple, dans ma ville…","Expliquez le lien entre cet exemple et votre argument."],["Y a-t-il des limites à votre position ?","Il est vrai que… Cependant…","Nuancez votre avis puis concluez."]]}'::jsonb),
('tef-a-loisirs', 'tef-a', true, '{"id":"tef-a-loisirs","name":"Loisirs & sorties","icon":"ticket","color":"lilac","title":"On se fait une toile ?","desc":"À partir d’une annonce, téléphonez pour obtenir des renseignements.","role":"un ami qui travaille au cinéma","context":"Vous avez lu cette annonce : « On se fait une toile ? — renseignements auprès de notre service d’accueil. » Vous appelez pour obtenir des informations. Vous êtes en vacances au Canada. Un ami travaille dans un cinéma. Demandez-lui des renseignements sur les films, les horaires et les tarifs pour choisir une séance.","axes":["films","horaires","tarifs","réservation"],"qa":[["Quels films sont à l’affiche cette semaine ?","Une comédie québécoise et un film d’aventure.","Lequel me conseillerais-tu ?"],["À quelle heure commence la prochaine séance ?","La comédie commence à 18 h et à 20 h 30.","Combien de temps dure le film ?"],["Combien coûte une place ?","Le tarif normal est de 14 dollars.","Y a-t-il un tarif étudiant ?"],["Faut-il réserver à l’avance ?","C’est préférable pour la séance du soir.","Peut-on réserver directement en ligne ?"],["Les films sont-ils en français ?","Oui, la comédie est en français et le film d’aventure est sous-titré.","Est-ce que les sous-titres sont en français aussi ?"]],"format":"tef-a"}'::jsonb),
('tef-a-transport', 'tef-a', true, '{"id":"tef-a-transport","name":"Transports","icon":"train","color":"sand","title":"La ville à portée de main","desc":"À partir d’une annonce, téléphonez pour obtenir des renseignements.","role":"un agent des transports","context":"Vous avez lu cette annonce : « La ville à portée de main — renseignements auprès de notre service d’accueil. » Vous appelez pour obtenir des informations. Vous découvrez une nouvelle ville. Demandez à un agent des renseignements sur les transports en commun, les horaires et les tarifs.","axes":["lignes","horaires","abonnements","trajet"],"qa":[["Quels transports desservent le centre-ville ?","Le métro et les lignes de bus 4 et 12.","Quel est le moyen le plus rapide ?"],["À quelle heure passe le dernier métro ?","À minuit en semaine et à une heure le samedi.","Y a-t-il des bus de nuit ?"],["Combien coûte un abonnement mensuel ?","Il coûte 45 euros et comprend les bus et le métro.","Existe-t-il une réduction pour les étudiants ?"],["Où puis-je acheter les tickets ?","Aux bornes dans les stations ou sur notre application.","Peut-on payer par carte bancaire ?"],["Comment rejoindre la gare depuis ici ?","Prenez la ligne 2 et descendez au quatrième arrêt.","Dois-je changer de ligne ?"]],"format":"tef-a"}'::jsonb),
('tef-a-association', 'tef-a', true, '{"id":"tef-a-association","name":"Vie associative","icon":"heart","color":"sage","title":"Donner du temps, créer du lien","desc":"À partir d’une annonce, téléphonez pour obtenir des renseignements.","role":"un agent du bureau des associations","context":"Vous avez lu cette annonce : « Donner du temps, créer du lien — renseignements auprès de notre service d’accueil. » Vous appelez pour obtenir des informations. Vous souhaitez devenir bénévole dans votre quartier. Interrogez un agent d’accueil sur les associations, les activités, les publics et les disponibilités nécessaires.","axes":["activités","publics","planning","inscription"],"qa":[["Quelles associations recherchent des bénévoles ?","Une banque alimentaire et une association de soutien scolaire.","Laquelle a le plus besoin d’aide actuellement ?"],["Quelles activités pourrais-je faire ?","Distribuer des repas ou accompagner des enfants dans leurs devoirs.","Une expérience particulière est-elle nécessaire ?"],["À quel public s’adressent ces actions ?","Aux familles du quartier et aux enfants de 6 à 12 ans.","Combien de personnes sont accueillies ?"],["Quels sont les horaires proposés ?","Le mercredi après-midi et le samedi matin.","Puis-je venir seulement deux fois par mois ?"],["Comment puis-je m’inscrire ?","Remplissez ce formulaire puis rencontrez le responsable.","Y a-t-il une formation avant de commencer ?"]],"format":"tef-a"}'::jsonb),
('tef-b-atelier', 'tef-b', true, '{"name":"Expression orale","icon":"mic","color":"sage","axes":[],"role":"un examinateur","id":"tef-b-atelier","format":"tef-b","title":"Un atelier de cuisine ensemble","desc":"Présentez une annonce et convainquez votre ami.","context":"Vous avez lu cette annonce : « Atelier cuisine du monde — chaque samedi à 10 h, 25 € par personne, ingrédients inclus. Une première séance à moitié prix. Centre culturel du quartier. » Présentez-la à un ami et convainquez-le de participer avec vous. Répondez à ses objections.","qa":[["Présentez un avantage concret de cette proposition.","Je ne sais pas cuisiner.","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."],["Présentez un avantage concret de cette proposition.","Je travaille parfois le samedi.","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."],["Présentez un avantage concret de cette proposition.","Cela coûte trop cher.","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."]]}'::jsonb),
('tef-b-velo', 'tef-b', true, '{"name":"Expression orale","icon":"mic","color":"sage","axes":[],"role":"un examinateur","id":"tef-b-velo","format":"tef-b","title":"Au travail à vélo","desc":"Présentez une annonce et convainquez votre ami.","context":"Vous avez lu cette annonce : « Vélo-partage — abonnement mensuel à 20 €, stations près du métro, casque conseillé. Trajets de moins de 30 minutes inclus. » Présentez-la à un ami et convainquez-le de participer avec vous. Répondez à ses objections.","qa":[["Présentez un avantage concret de cette proposition.","La route me fait peur.","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."],["Présentez un avantage concret de cette proposition.","Et quand il pleut ?","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."],["Présentez un avantage concret de cette proposition.","Je suis trop loin du bureau.","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."]]}'::jsonb),
('tef-b-benevolat', 'tef-b', true, '{"name":"Expression orale","icon":"mic","color":"sage","axes":[],"role":"un examinateur","id":"tef-b-benevolat","format":"tef-b","title":"Un samedi solidaire","desc":"Présentez une annonce et convainquez votre ami.","context":"Vous avez lu cette annonce : « La banque alimentaire cherche des bénévoles le samedi de 9 h à 12 h. Formation sur place. Participation possible une fois par mois. » Présentez-la à un ami et convainquez-le de participer avec vous. Répondez à ses objections.","qa":[["Présentez un avantage concret de cette proposition.","Je manque de temps.","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."],["Présentez un avantage concret de cette proposition.","Je ne connais personne.","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."],["Présentez un avantage concret de cette proposition.","Je ne sais pas comment aider.","Reformulez cette objection, proposez une solution et expliquez un bénéfice pour votre ami."]]}'::jsonb)
